22	        this.projectId = projectId;
23	        this.amount = amount;
24	        this.status = status;
25	        this.issuedDate = issuedDate;
26	        this.dueDate = dueDate;
27	    }
28	
29	    public long getId() {
30	        return id;
31	    }
